import{Component,Port}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{THREE,materials,mesh,FACE,portQuaternion,roundedRect,capsule,box,solid,hole,ring,cylinder,lathe}from'./geometry.js';import data from'./geometry-data.js';import{NativeReset}from'./NativeReset.js';import{LegoClip,Wall1515}from'./accessories.js';import{spec}from'./dimensions.js';
const black=()=>materials.plastic(0x17201a,{roughness:.8}),tin=()=>materials.metal(0xb8bfb5,{roughness:.45});
