function screws(host){return[-8,8].map(x=>{const s=new THREE.Shape();s.absarc(0,0,1.55,0,Math.PI*2,false);const h=new THREE.Path();for(let i=0;i<6;i++){const angle=Math.PI*i/3;i?h.lineTo(.64*Math.cos(angle),.64*Math.sin(angle)):h.moveTo(.64,0);}h.closePath();s.holes.push(h);const head=solid(host.body,s,.4,[x,-19.5,-6.55],tin(),'M5Camera-X fixed actual rear blind hex screw head'),floor=cylinder(host.body,.65,.1,[x,-19.5,-6.1],black(),'M5Camera-X actual blind screw recess floor'),shank=cylinder(host.body,.7,8.3,[x,-19.5,-1.95],tin(),'M5Camera-X actual fixed retaining screw shank');return{head,floor,shank};});}
export function buildM5CameraX(host,{mount='none'}={}){if(!['none','lego','wall1515'].includes(mount))throw new RangeError('M5Camera-X mount must be none,lego or wall1515');const parts=addCadParts(host,data.filter(p=>['front','rear'].includes(p.role)),{white:materials.plastic(0xe4e3d8,{roughness:.71})}),front=Object.values(parts).find(p=>p.name.endsWith('front')),rear=Object.values(parts).find(p=>p.name.endsWith('rear')),pcb=board(host),input=grove(host),usbParts=usb(host),button=reset(host,front),optics=camera(host),fixing=screws(host),mountPort=host.add(new Port({id:'mount',label:'Own static rear mounting clip/adapter',connector:spec.mount.connector,position:spec.mount.position,quaternion:portQuaternion('back'),hitSize:[18,1,27],meta:{role:'mechanical-mount',face:'back',scope:'One actual own static LEGO clip or Wall-1515 only;no electrical or hinge behavior'}}));host.m5CameraXAssembly={parts,front,rear,board:pcb,input,usb:usbParts,reset:button,optical:optics,screws:fixing,mount:mountPort};host.unitStickers=[];if(mount==='lego')mountPort.attach(new LegoClip());if(mount==='wall1515')mountPort.attach(new Wall1515());}
